  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Propagates water outward from the source, filling connected pipes whose connections match, up to the given distance, using BFS-style expansion.
   * Algorithm:
   *   1. Initialize a BFS queue seeded with the source cell (assumed already filled via fillBeginTile()).
   *   2. Maintain a visited set / per-tile distance tracking relative to the source.
   *   3. While the queue is not empty and the current distance is within the input distance:
   *        a. Dequeue the front cell.
   *        b. For each of the four Direction values, compute the adjacent coordinate using Pa19Helper.getOffset(dir).
   *        c. If the adjacent cell is out of bounds or already visited, skip.
   *        d. If the current cell's pipe has a connection in direction dir AND the adjacent cell's pipe has a connection in Pa19Helper.getOpposite(dir), the connection matches; mark the adjacent cell as filled and enqueue it.
   *   4. After BFS, record prevFilledTiles as the number of tiles newly filled in this round and prevFilledDistance as the input distance.
   * Related Features: filledTiles (list of newly filled coordinates), sourceCell, prevFilledTiles, prevFilledDistance, cell (Cell[][] grid).
   * Related Classes: Direction, Pipe, Coordinate, FillableCell, Pa19Helper
   * Input:
   *   - distance (int): the maximum BFS distance from the source at which water should fill pipes; each round increments this value by 1.
   * Output: void
   * Pre-condition:
   *   - The source cell exists and has been marked as filled by fillBeginTile().
   *   - distance is a non-negative integer representing how far water has progressed from the source.
   * Post-condition:
   *   - All reachable pipe cells whose distance from the source is less than or equal to the input distance and whose connection directions match an adjacent filled pipe are marked as filled.
   *   - prevFilledTiles is updated to the number of newly filled tiles in this round.
   *   - prevFilledDistance is updated to the input distance value.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    Deque<Cell> queue = new ArrayDeque<Cell>();
    HashMap<Cell, Integer> dist = new HashMap<Cell, Integer>();

    queue.add(getSourceCell());
    dist.put(getSourceCell(), Integer.valueOf(0));

    int newFilled = 0;

    while (!queue.isEmpty())
    {
      Cell current = queue.poll();
      int d = dist.get(current).intValue();
      if (d >= distance)
      {
        continue;
      }

      for (Direction dir : Direction.VALUES)
      {
        Coordinate offset = helper.getOffset(dir);
        Coordinate adjCoord = current.getCoord().add(offset);
        int r = adjCoord.getRow();
        int c = adjCoord.getCol();

        if (r < 0 || r >= getRows() || c < 0 || c >= getCols())
        {
          continue;
        }

        Cell adj = getCell()[r][c];
        if (adj == null || dist.containsKey(adj))
        {
          continue;
        }

        boolean currentHasConn = false;
        if (current instanceof FillableCell)
        {
          Pipe p = ((FillableCell) current).getPipe();
          currentHasConn = p != null && p.getConnections().contains(dir);
        }
        else if (current instanceof TerminationCell)
        {
          currentHasConn = ((TerminationCell) current).getPointingTo() == dir;
        }

        boolean adjHasConn = false;
        if (adj instanceof FillableCell)
        {
          Pipe p = ((FillableCell) adj).getPipe();
          adjHasConn = p != null && p.getConnections().contains(helper.getOpposite(dir));
        }

        if (currentHasConn && adjHasConn)
        {
          if (adj instanceof FillableCell)
          {
            ((FillableCell) adj).getPipe().setFilled(true);
          }
          else if (adj instanceof TerminationCell)
          {
            ((TerminationCell) adj).setFilled(true);
          }

          Coordinate fc = Pa19Factory.eINSTANCE.createCoordinate();
          fc.setRow(r);
          fc.setCol(c);
          getFilledTiles().add(fc);

          newFilled++;
          queue.add(adj);
          dist.put(adj, Integer.valueOf(d + 1));
        }
      }
    }

    this.prevFilledTiles = newFilled;
    this.prevFilledDistance = Integer.valueOf(distance);
  }

